});
const base = "https://sheets.googleapis.com/v4/spreadsheets/" + config.spreadsheetId;
return [
  {
    json: {
      config,
      read:
        base +
        "/values:batchGet?majorDimension=ROWS&valueRenderOption=UNFORMATTED_VALUE&ranges=" +
        encodeURIComponent(config.sheet),
      write: base + "/values:batchUpdate",
    },
    pairedItem: { item: 0 },
  },
];

function publicMedia(value) {
  if (typeof value !== "string") return "";
  const url = value.trim();
  return /^https:\/\/(?:[a-z\d](?:[a-z\d-]*[a-z\d])?\.)+[a-z]{2,63}(?:[/?#][^\s\\]*)?$/i.test(url)
    ? url
    : "";
}

function unquoteSheet(range) {
  return range.replace(/^'(.*)'!/, (_match, tab) => tab.replace(/''/g, "'") + "!");
}

function queueRows(response, config) {
  const ranges = response?.valueRanges;
  if (
    response?.spreadsheetId !== config.spreadsheetId ||
    !Array.isArray(ranges) ||
    ranges.length !== 1 ||
    typeof ranges[0]?.range !== "string" ||
    !unquoteSheet(ranges[0].range).startsWith(unquoteSheet(config.sheet + "!") + "A1:")
  ) {
    throw Error("Google Sheets did not return the configured publishing worksheet.");
  }
  const values = ranges[0]?.values;
  if (!Array.isArray(values) || !Array.isArray(values[0]))
    throw Error("Add the queue headers in the first row.");
  const requiresImage = config.destinations.some(
    ({ platform }) => platform === "bluesky" || platform === "pinterest",
  );
  const requiresTitle = config.destinations.some(({ platform }) => platform === "youtube");
  const headers = values[0].map((value) => String(value ?? "").trim());
  const required = [
    "URL VIDEO",
    "DESCRIPTION",
    "Titre",
    "STATUS",
    "SUBMISSION IDS",
    ...(requiresImage ? ["IMAGE URL"] : []),
  ];
  for (const header of required)
    if (headers.filter((value) => value === header).length !== 1)
      throw Error("Add exactly one column named " + header + ".");
  const get = (row, name) => row[headers.indexOf(name)];
  return values.slice(1).flatMap((row, index) => {
    const rowNumber = index + 2,
      status = String(get(row, "STATUS") ?? "")
        .trim()
        .toUpperCase();
    const video = get(row, "URL VIDEO");
    if (!video || (status && status !== "READY") || String(get(row, "SUBMISSION IDS") ?? "").trim())
      return [];
    const mediaUrl = publicMedia(video),
      imageUrl = publicMedia(get(row, "IMAGE URL"));
    const title = String(get(row, "Titre") ?? "").trim(),
      text = String(get(row, "DESCRIPTION") ?? "");
    if (!mediaUrl || (requiresImage && !imageUrl) || (requiresTitle && !title))
      throw Error("Check the media URLs and title in row " + rowNumber + ".");
    return [
      {
        rowNumber,
        mediaUrl,
        imageUrl,
        title,
        text,
        statusColumn: headers.indexOf("STATUS"),
        receiptsColumn: headers.indexOf("SUBMISSION IDS"),
      },
    ];
  });
}

const response = $input.first().json,
  settings = $("Configure the sheet and destinations").first().json;
if (response.statusCode !== 200) throw Error("Google Sheets did not return the queue.");
return queueRows(response.body, settings.config).map((row) => ({
  json: { row },
  pairedItem: { item: 0 },
}));

function sheetCell(sheet, column, row) {
  let letters = "";
  for (let index = column + 1; index > 0; index = Math.floor((index - 1) / 26)) {
    letters = String.fromCharCode(65 + ((index - 1) % 26)) + letters;
  }
  return sheet + "!" + letters + row;
}

function sheetRequest(config, row, status, receipts) {
  const make = (column, content) => ({
    range: sheetCell(config.sheet, column, row.rowNumber),
    values: [[content]],
  });
  const data = [make(row.statusColumn, status)];
  if (receipts) data.push(make(row.receiptsColumn, JSON.stringify(receipts)));
  return {
    spreadsheetId: config.spreadsheetId,
    valueInputOption: "RAW",
    includeValuesInResponse: true,
    responseValueRenderOption: "UNFORMATTED_VALUE",
    data,
  };
}

function unquoteSheet(range) {
  return range.replace(/^'(.*)'!/, (_match, tab) => tab.replace(/''/g, "'") + "!");
}

function checkSheet(response, request) {
  if (
    response?.spreadsheetId !== request.spreadsheetId ||
    response.totalUpdatedCells !== request.data.length ||
    response?.responses?.length !== request.data.length ||
    request.data.some((cell, i) => {
      const result = response.responses[i];
      const exact = unquoteSheet(cell.range);
      return (
        result.updatedCells !== 1 ||
        typeof result.updatedRange !== "string" ||
        ![exact, exact + ":" + exact.slice(exact.lastIndexOf("!") + 1)].includes(
          unquoteSheet(result.updatedRange),
        ) ||
        result.updatedData?.values?.[0]?.[0] !== cell.values[0][0]
      );
    })
  )
    throw Error("Google Sheets did not confirm the publishing status on the expected row.");
}

const row = $input.first().json.row,
