const response = $input.first().json;
const fold = $("Collect the post submission IDs").isExecuted,
  hold = $("Record an unconfirmed upload").isExecuted;
const matched = (node) => {
  try {
    return $(node).itemMatching(0).json;
  } catch {
    return null;
  }
};
const origin =
  (fold && matched("Collect the post submission IDs")) ||
  (hold && matched("Record an unconfirmed upload"));
if (response.statusCode !== 200 || !origin)
  throw Error("Google Sheets did not confirm the queue outcome.");
