  ...origin.request,
  spreadsheetId: $("Configure the sheet and destinations").first().json.config.spreadsheetId,
});
return [
  {
    json: { rowNumber: origin.rowNumber, status: origin.status, receipts: origin.receipts },
    pairedItem: { item: 0 },
